package com.ecole.gestion_scolaire.hr.service; import com.ecole.gestion_scolaire.hr.dto.*; import com.ecole.gestion_scolaire.hr.entity.*; import com.ecole.gestion_scolaire.hr.enums.*; import com.ecole.gestion_scolaire.hr.repository.*; import com.ecole.gestion_scolaire.school.repository.*; import com.ecole.gestion_scolaire.common.exception.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service @Transactional public class TeachingAssignmentService { private final TeachingAssignmentRepository repo; private final TeacherRepository teachers; private final SubjectRepository subjects; private final SchoolYearRepository years; private final ClassGroupRepository classes; private final TeacherSubjectRepository teacherSubjects; public TeachingAssignmentService(TeachingAssignmentRepository r,TeacherRepository t,SubjectRepository s,SchoolYearRepository y,ClassGroupRepository c,TeacherSubjectRepository ts){repo=r;teachers=t;subjects=s;years=y;classes=c;teacherSubjects=ts;} public TeachingAssignmentResponse create(TeachingAssignmentRequest q){if(repo.existsBySchoolYearIdAndTeacherIdAndSubjectIdAndClassGroupIdAndStatus(q.schoolYearId(),q.teacherId(),q.subjectId(),q.classGroupId(),AssignmentStatus.ACTIVE))throw new BusinessRuleException("Cette affectation existe déjà."); if(!teacherSubjects.existsByTeacherIdAndSubjectId(q.teacherId(),q.subjectId()))throw new BusinessRuleException("La matière doit d'abord être rattachée à l'enseignant.");var c=classes.findById(q.classGroupId()).orElseThrow(()->new ResourceNotFoundException("Classe introuvable"));if(!c.getSchoolYear().getId().equals(q.schoolYearId()))throw new BusinessRuleException("La classe n'appartient pas à l'année scolaire sélectionnée.");var a=new TeachingAssignment();a.setSchoolYear(years.findById(q.schoolYearId()).orElseThrow(()->new ResourceNotFoundException("Année scolaire introuvable")));a.setTeacher(teachers.findById(q.teacherId()).orElseThrow(()->new ResourceNotFoundException("Enseignant introuvable")));a.setSubject(subjects.findById(q.subjectId()).orElseThrow(()->new ResourceNotFoundException("Matière introuvable")));a.setClassGroup(c);a.setStartDate(q.startDate());a.setEndDate(q.endDate());return map(repo.save(a));} public TeachingAssignmentResponse end(Long id,java.time.LocalDate end){var a=get(id);a.setEndDate(end);a.setStatus(AssignmentStatus.ENDED);return map(repo.save(a));} @Transactional(readOnly=true) public List<TeachingAssignmentResponse> byTeacher(Long id){return repo.findByTeacherIdOrderByStartDateDesc(id).stream().map(this::map).toList();} @Transactional(readOnly=true) public List<TeachingAssignmentResponse> byClass(Long y,Long c){return repo.findBySchoolYearIdAndClassGroupIdAndStatus(y,c,AssignmentStatus.ACTIVE).stream().map(this::map).toList();} private TeachingAssignment get(Long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Affectation introuvable"));} private TeachingAssignmentResponse map(TeachingAssignment a){var p=a.getTeacher().getEmployee().getPerson();return new TeachingAssignmentResponse(a.getId(),a.getSchoolYear().getId(),a.getSchoolYear().getLabel(),a.getTeacher().getId(),p.getFirstName()+" "+p.getLastName(),a.getSubject().getId(),a.getSubject().getName(),a.getClassGroup().getId(),a.getClassGroup().getName(),a.getStartDate(),a.getEndDate(),a.getStatus().name());}}